expression_harness:
import fs from "node:fs";
import assert from "node:assert/strict";
import { Lexer, Parser, Evaluator, data } from "@actions/expressions";
const input=JSON.parse(fs.readFileSync(new URL("./expressions-exact-ref.json",import.meta.url),"utf8"));
function datum(x) {
 if(typeof x==="string")return new data.StringData(x);
 if(typeof x==="boolean")return new data.BooleanData(x);
 return new data.Dictionary(...Object.entries(x).map(([key,value])=>({key,value:datum(value)})));
}
const always={name:"always",minArgs:0,maxArgs:0,call:()=>new data.BooleanData(true)};
function evaluate(source,context) {
 const raw=source.trim().replace(/^\$\{\{\s*/,"").replace(/\s*\}\}$/,"");
 const expression=new Parser(new Lexer(raw).lex().tokens,["github","inputs","steps","env"],[always]).parse();
 return new Evaluator(expression,datum(context),new Map([["always",always]])).evaluate().coerceString()==="true";
}
const results=[];
for(const c of input.cases){
 const output=c.admission.output.trim();
 const admitted=c.admission.returncode===0 && output==="canonical_main=true";
 const context={github:c.github,inputs:c.inputs,env:{MARKETING_PUBLISH_ENABLED:c.armed},
  steps:{main_ref:{outputs:{canonical_main:admitted?"true":""}},
         publisher_checkout:{outcome:c.checkout_outcome}}};
 const job=evaluate(input.publish,context),read=evaluate(input.readback,context);
 const execution=job&&admitted&&c.checkout_outcome==="success";
 const sends=execution&&evaluate(input.sender,context),recalls=execution&&evaluate(input.recall,context);
 const commit=job&&evaluate(input.commit,context),liveness=job&&evaluate(input.liveness,context);
 const actual=[execution,read,sends,recalls,commit,liveness];
 assert.deepEqual(actual,c.expected,c.name);
 const prior={publish:evaluate(input.before_publish,context),readback:evaluate(input.before_readback,context)};
 assert.equal(read,prior.readback,c.name+" readback parity");
 results.push({...c,job_filter:job,admitted,canonical_execution:execution,readback:read,
               sender_step:sends,recall_step:recalls,commit_step:commit,liveness_step:liveness,prior});
}
const result={package:"@actions/expressions",version:"0.3.61",cases:results,all_passed:true,
 limitation:"Actual extracted shell and official expression evaluator; default-success prerequisites are represented by successful admission and checkout. Not hosted Actions execution."};
fs.writeFileSync(new URL("./result-exact-ref.json",import.meta.url),JSON.stringify(result,null,2)+"\n");
console.log(JSON.stringify({cases:results.length,all_passed:true,readback_unchanged:true,
  case_variants_blocked:results.filter(x=>x.name.startsWith("case variant")&&!x.readback).every(x=>!x.canonical_execution&&!x.commit_step&&!x.liveness_step)}));
